#!/usr/bin/env node
import { mkdir, readFile, rename, stat, writeFile } from 'node:fs/promises';
import { basename, dirname, resolve } from 'node:path';
import { homedir } from 'node:os';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import { removeAtPath, getAtPath } from '../src/merge.js';
import { backup } from '../src/backup.js';
import { c, confirm, closeUi, wrap } from '../src/ui.js';
import { listConfs } from '../src/list.js';
import { runBatch, runRemoveBatch } from '../src/batch.js';
import { parseInstallArgs, validateInstallPolicy, CliArgsError } from '../src/cli-args.js';
import { expandIncludes } from '../src/expand-includes.js';
import { validateAgainstSchema } from '../src/validate.js';
import { printValidationIssue } from '../src/validation-output.js';
const CACHE_DIR = process.env.OPENCODE_PRESETS_CACHE
    ? resolve(process.env.OPENCODE_PRESETS_CACHE)
    : resolve(homedir(), '.cache/opencode-presets');
const BACKUP_DIR = resolve(CACHE_DIR, 'backups');
const TARGET = process.env.OPENCODE_CONFIG
    ? resolve(process.env.OPENCODE_CONFIG)
    : resolve(homedir(), '.config/opencode/opencode.json');
const __dirname = dirname(fileURLToPath(import.meta.url));
// __dirname is either <repo>/bin (running source via ts) or
// <repo>/dist/bin (running compiled). In both cases the presets dir
// lives next to package.json, which we find by walking up.
const REPO_ROOT = findPackageRoot(__dirname);
function findPackageRoot(start) {
    let dir = start;
    while (true) {
        const parent = dirname(dir);
        if (parent === dir)
            return start; // hit fs root, give up
        // package.json sibling check happens implicitly by stepping up
        // out of bin/ and dist/. We bail when we reach a dir whose parent
        // matches the package layout.
        if (dir.endsWith('/dist') || dir.endsWith('/bin')) {
            dir = parent;
            continue;
        }
        return dir;
    }
}
// Search path for `list` (in priority order):
//   1. dirs from OPENCODE_PRESETS_PATH (colon-separated; for team/personal repos)
//   2. ./presets/              (CWD-relative, honoured when it exists)
//   3. <repo>/presets/         (shipped baseline)
const DEFAULT_PRESET_DIRS = [
    ...(process.env.OPENCODE_PRESETS_PATH
        ? process.env.OPENCODE_PRESETS_PATH.split(':').filter(Boolean).map(p => resolve(p))
        : []),
    resolve(process.cwd(), 'presets'),
    resolve(REPO_ROOT, 'presets'),
];
const SCHEMA_URL = 'https://opencode.ai/config.json';
const EMPTY_CONFIG = { '$schema': SCHEMA_URL };
async function main() {
    const argv = process.argv.slice(2);
    if (argv.length === 0 || argv[0] === '-h' || argv[0] === '--help') {
        printUsage();
        process.exit(argv.length === 0 ? 1 : 0);
    }
    if (argv[0] === '-V' || argv[0] === '--version') {
        const raw = await readFile(resolve(REPO_ROOT, 'package.json'), 'utf8');
        console.log(`v${JSON.parse(raw).version}`);
        process.exit(0);
    }
    const sub = argv[0];
    if (sub === 'list') {
        const rest = argv.slice(1);
        const long = rest.includes('-l') || rest.includes('--long');
        const all = rest.includes('-a') || rest.includes('--all');
        const positional = rest.filter(a => a !== '-l' && a !== '--long' && a !== '-a' && a !== '--all');
        const dirs = positional[0] ? [resolve(positional[0])] : DEFAULT_PRESET_DIRS;
        await listConfs(dirs, { long, all, repoRoot: REPO_ROOT });
        return;
    }
    if (sub === 'validate') {
        await runValidate(argv.slice(1));
        return;
    }
    if (sub === 'reset') {
        if (argv.length === 1) {
            await runResetAll();
            return;
        }
        if (argv.length !== 2) {
            printUsage();
            process.exit(1);
        }
        await runReset(argv[1]);
        return;
    }
    if (sub === 'install') {
        let parsed;
        try {
            parsed = parseInstallArgs(argv.slice(1));
        }
        catch (e) {
            if (e instanceof CliArgsError) {
                console.error(c.err('error: ') + e.message);
                console.error('');
                printUsage();
                process.exit(1);
            }
            throw e;
        }
        const { resets, confPaths, setValues } = parsed;
        if (confPaths.length === 0 && resets.length === 0) {
            printUsage();
            process.exit(1);
        }
        const policyError = validateInstallPolicy(parsed);
        if (policyError !== null) {
            console.error(c.err('error: ') + policyError);
            process.exit(1);
        }
        const resolved = await expandConfArgs(confPaths);
        await runBatch({
            resets,
            confPaths: resolved,
            setValues,
            target: TARGET,
            schema: SCHEMA_URL,
            cacheDir: CACHE_DIR,
            backupDir: BACKUP_DIR,
        });
        return;
    }
    if (sub === 'remove') {
        const args = argv.slice(1);
        if (args.length === 0) {
            printUsage();
            process.exit(1);
        }
        const resolved = await expandConfArgs(args);
        await runRemoveBatch({
            confPaths: resolved,
            target: TARGET,
            schema: SCHEMA_URL,
            cacheDir: CACHE_DIR,
            backupDir: BACKUP_DIR,
        });
        return;
    }
    printUsage();
    process.exit(1);
}
// Shipped presets that changed name. Only consulted when nothing by the old
// name exists, so a user's own preset of that name still wins.
const RENAMED = {
    'opencode-planify-german': 'planify-german',
    'plugin-opencode-planify-german': 'plugin-planify-german',
    'instructions-opencode-planify-german': 'instructions-planify-german',
    'skill-opencode-planify-german': 'skill-planify-german',
};
// If `arg` looks like a path (contains a slash, ends in .conf, or
// resolves to an existing file), use it as-is. Otherwise treat it as
// a bare preset name and search DEFAULT_PRESET_DIRS for `<arg>.conf`.
async function resolveConfArg(arg) {
    const looksLikePath = arg.includes('/') || arg.endsWith('.conf');
    if (looksLikePath)
        return resolve(arg);
    for (const dir of DEFAULT_PRESET_DIRS) {
        const candidate = resolve(dir, arg + '.conf');
        if (await fileExists(candidate))
            return candidate;
    }
    if (RENAMED[arg]) {
        console.error(c.err('error: ') + `"${arg}" was renamed — use "${RENAMED[arg]}". What it writes is unchanged.`);
        process.exit(1);
    }
    console.error(c.err('error: ') + `no preset named "${arg}" found in:`);
    for (const dir of DEFAULT_PRESET_DIRS)
        console.error('  ' + dir);
    console.error('  ' + c.dim('(set OPENCODE_PRESETS_PATH to add more dirs, or pass an explicit path)'));
    process.exit(1);
}
// Resolve each CLI argument, then flatten any @include bundles into the leaf
// presets they list. Bundles carry no @path and no body, so they must never
// reach runBatch/runRemoveBatch — only their expansion does.
async function expandConfArgs(args) {
    const resolved = await Promise.all(args.map(resolveConfArg));
    const bundles = [];
    let expanded;
    try {
        expanded = await expandIncludes(resolved, resolveIncludeRef, m => bundles.push(m));
    }
    catch (e) {
        console.error(c.err('error: ') + (e instanceof Error ? e.message : String(e)));
        process.exit(1);
    }
    // A bundle is expanded away before the summary renders, so its own
    // description — where it says what it is and what it is not — would never be
    // seen. Print it here, ahead of the list of presets it turned into.
    for (const m of bundles) {
        console.log('');
        console.log(c.bold(m.name) + c.meta(` v${m.version}`) + c.dim(' — bundle of ') +
            c.bold(String(m.includes.length)) + c.dim(' presets'));
        console.log(wrap(m.description, 72, '    '));
    }
    return expanded;
}
// An @include value is either a path relative to the including file, or a bare
// preset name looked up in the same search path as a CLI argument.
async function resolveIncludeRef(ref, fromFile) {
    if (ref.includes('/') || ref.endsWith('.conf'))
        return resolve(dirname(fromFile), ref);
    for (const dir of DEFAULT_PRESET_DIRS) {
        const candidate = resolve(dir, ref + '.conf');
        if (await fileExists(candidate))
            return candidate;
    }
    if (RENAMED[ref]) {
        console.error(c.err('error: ') + `${basename(fromFile, '.conf')} includes "${ref}", which was renamed to "${RENAMED[ref]}" — change the @include.`);
        process.exit(1);
    }
    console.error(c.err('error: ') + `${basename(fromFile, '.conf')} includes "${ref}", which was not found in:`);
    for (const dir of DEFAULT_PRESET_DIRS)
        console.error('  ' + dir);
    process.exit(1);
}
async function fileExists(path) {
    try {
        await stat(path);
        return true;
    }
    catch {
        return false;
    }
}
async function runResetAll() {
    const existing = await loadJsonOrNull(TARGET);
    if (existing === null) {
        console.log(c.dim('opencode.json does not exist — nothing to reset.'));
        return;
    }
    if (JSON.stringify(existing) === JSON.stringify(EMPTY_CONFIG)) {
        console.log(c.dim('opencode.json is already at the minimal baseline — nothing to reset.'));
        return;
    }
    console.log('');
    console.log(c.bold('Target') + c.meta(': ') + TARGET);
    console.log('');
    console.log(c.warn('⚠  reset (no path) wipes the ENTIRE opencode.json and replaces it with'));
    console.log(c.warn('   a minimal baseline:'));
    console.log('');
    console.log('     ' + JSON.stringify(EMPTY_CONFIG, null, 2).replace(/\n/g, '\n     '));
    console.log('');
    console.log(c.warn('   This deletes every preset, every MCP server, every permission rule,'));
    console.log(c.warn('   every hand-edit. Backup is taken first; you can restore from'));
    console.log(c.warn('   ~/.cache/opencode-presets/backups/ if needed.'));
    console.log('');
    const proceed = await confirm('Reset to minimal baseline?');
    if (!proceed) {
        console.log(c.dim('declined.'));
        return;
    }
    await validateOrAbort(EMPTY_CONFIG, 'pre-write');
    let backupPath = null;
    try {
        backupPath = await backup(TARGET, BACKUP_DIR);
    }
    catch (e) {
        console.error(c.err('error: backup failed: ') + (e instanceof Error ? e.message : String(e)));
        process.exit(1);
    }
    if (backupPath)
        console.log('  ' + c.ok('✓') + ' backed up → ' + c.meta(backupPath));
    await mkdir(dirname(TARGET), { recursive: true });
    const tmp = TARGET + '.tmp';
    await writeFile(tmp, JSON.stringify(EMPTY_CONFIG, null, 2) + '\n', 'utf8');
    await rename(tmp, TARGET);
    await validateWritten();
    console.log('  ' + c.ok('✓') + ' reset to minimal baseline');
}
async function runReset(path) {
    const existing = await loadJsonOrNull(TARGET);
    if (existing === null) {
        console.log(c.dim('opencode.json does not exist — nothing to reset.'));
        return;
    }
    const current = getAtPath(existing, path);
    if (current === undefined) {
        console.log(c.dim(`nothing at ${path} — nothing to reset.`));
        return;
    }
    console.log('');
    console.log(c.bold('Target') + c.meta(': ') + TARGET);
    console.log(c.bold('Path  ') + c.meta(': ') + path);
    console.log(c.bold('Current value:'));
    console.log('  ' + c.warn('- ') + truncJson(current, 400));
    console.log('');
    console.log('  ' + c.warn('⚠  reset deletes EVERYTHING at this path, including any rules and'));
    console.log('  ' + c.warn('   entries you set by hand. There is no per-preset distinction.'));
    console.log('');
    const proceed = await confirm('Reset?');
    if (!proceed) {
        console.log(c.dim('declined.'));
        return;
    }
    const { next } = removeAtPath(existing, path, undefined, 'replace');
    await validateOrAbort(next, 'pre-write');
    let backupPath = null;
    try {
        backupPath = await backup(TARGET, BACKUP_DIR);
    }
    catch (e) {
        console.error(c.err('error: backup failed: ') + (e instanceof Error ? e.message : String(e)));
        process.exit(1);
    }
    if (backupPath)
        console.log('  ' + c.ok('✓') + ' backed up → ' + c.meta(backupPath));
    await mkdir(dirname(TARGET), { recursive: true });
    const tmp = TARGET + '.tmp';
    await writeFile(tmp, JSON.stringify(next, null, 2) + '\n', 'utf8');
    await rename(tmp, TARGET);
    await validateWritten();
    console.log('  ' + c.ok('✓') + ' reset ' + c.bold(path));
}
async function validateOrAbort(config, phase) {
    const result = await validateAgainstSchema(config, CACHE_DIR);
    if (result.skipped) {
        console.error(c.warn('⚠  ') + result.errors.join('; '));
        return;
    }
    if (result.ok)
        return;
    if (phase === 'pre-write') {
        console.error('');
        console.error(c.err('✗ ') + c.bold('schema validation failed — would have produced an invalid opencode.json'));
        for (const e of result.errors.slice(0, 12))
            console.error('  ' + c.err(e));
        if (result.errors.length > 12)
            console.error(c.dim(`  … (+${result.errors.length - 12} more)`));
        console.error(c.err('aborting; opencode.json not modified.'));
        process.exit(1);
    }
    else {
        console.error('');
        console.error(c.err('⚠  post-write validation FAILED — opencode.json on disk does not match the schema.'));
        for (const e of result.errors.slice(0, 12))
            console.error('  ' + c.err(e));
    }
}
async function validateWritten() {
    try {
        const raw = await readFile(TARGET, 'utf8');
        await validateOrAbort(JSON.parse(raw), 'post-write');
    }
    catch (e) {
        console.error(c.err('⚠  could not re-read written file: ') +
            (e instanceof Error ? e.message : String(e)));
    }
}
async function runValidate(args) {
    if (args.length > 1) {
        printUsage();
        process.exit(1);
    }
    const mode = args[0] ?? 'config';
    if (mode !== 'config') {
        console.error(c.err('error: ') + 'validate target must be config (opencode 2 reads only opencode.json)');
        process.exit(1);
    }
    const outcome = await validateTargetFile('config', TARGET, SCHEMA_URL);
    if (outcome === 'read-error')
        process.exit(2);
    if (outcome === 'invalid')
        process.exit(1);
}
async function validateTargetFile(kind, path, schema) {
    let parsed;
    try {
        const raw = await readFile(path, 'utf8');
        parsed = JSON.parse(raw);
    }
    catch (e) {
        if (e.code === 'ENOENT') {
            console.log(c.dim(`${kind}: missing — skipped (${path})`));
            return 'missing';
        }
        const msg = e instanceof Error ? e.message : String(e);
        console.error(c.err(`✗ ${kind}: could not read or parse ${path}`));
        console.error('  ' + c.err(msg));
        return 'read-error';
    }
    const result = await validateAgainstSchema(parsed, CACHE_DIR, schema);
    if (result.skipped) {
        console.log(c.warn(`⚠ ${kind}: validation skipped (${path})`));
        for (const e of result.errors)
            console.error('  ' + c.warn(e));
        return 'skipped';
    }
    if (result.ok) {
        console.log(c.ok(`✓ ${kind}: valid (${path})`));
        return 'valid';
    }
    console.log(c.err(`✗ ${kind}: invalid (${path})`));
    for (const e of result.errors.slice(0, 12))
        printValidationIssue(e, c.err);
    if (result.errors.length > 12)
        console.error(c.dim(`  … (+${result.errors.length - 12} more)`));
    return 'invalid';
}
function truncJson(value, max) {
    const s = JSON.stringify(value, null, 2);
    return s.length <= max ? s : s.slice(0, max) + c.dim(` … (${s.length - max} more chars)`);
}
async function loadJsonOrNull(path) {
    try {
        return JSON.parse(await readFile(path, 'utf8'));
    }
    catch (e) {
        if (e.code === 'ENOENT')
            return null;
        throw e;
    }
}
